import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.ShowProfile{XUID: "2535413830400711"}
XUID = bytes.fromhex("1032353335343133383330343030373131")

# generated by gophertunnel b8bd735:
# packet.ShowProfile{XUID: ""}
EMPTY = bytes.fromhex("00")

GOLDENS = [
    pytest.param(v2225.ShowProfilePacket(player_xuid="2535413830400711"), XUID, id="xuid"),
    pytest.param(v2225.ShowProfilePacket(), EMPTY, id="empty"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_show_profile_is_packet_104(version):
    assert version.PACKETS[104] is version.ShowProfilePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_show_profile_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_show_profile_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_the_xuid_length_prefix_is_a_varint():
    packet = v2225.ShowProfilePacket(player_xuid="x" * 200)
    wire = bytes(packet)
    assert len(wire) == 202
    assert wire[:2] == bytes.fromhex("c801")
    assert v2225.ShowProfilePacket.from_bytes(wire) == packet
